def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_bids = []
    weak_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_hp = opp.get('hp', 0)
            opp_budget = opp.get('budget', 0)
            opp_nowater = opp.get('no_water_days', 0)
            if opp_hp <= 2 or opp_budget < 40 or opp_nowater >= 2:
                weak_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp_budget >= 60 and opp_hp > 2:
                    dangerous_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    danger_prev = max(dangerous_bids) if dangerous_bids else high_prev

    scarcity = (supply <= 17)
    medium_tight = (supply <= 19)
    urgent = (hp <= 2 or no_water >= 2)
    pressured = (hp <= 4 or no_water >= 1)
    endgame = (day >= 8)

    if urgent:
        target = max(92.0, danger_prev + 3.0)
        if scarcity:
            target = max(target, 118.0)
        if endgame:
            target += 6.0
        return float(min(budget, target))

    if scarcity:
        if danger_prev >= 120:
            target = danger_prev + 2.5
        elif danger_prev >= 95:
            target = danger_prev + 3.5
        else:
            target = 104.0
        if pressured:
            target += 6.0
        if endgame:
            target += 4.0
        return float(min(budget, target))

    if medium_tight:
        if weak_count >= 2 and hp > 4:
            target = 54.0
        else:
            if danger_prev >= 115:
                target = 86.0
            elif danger_prev >= 90:
                target = danger_prev - 8.0
            else:
                target = 72.0
            if pressured:
                target += 8.0
        return float(min(budget, target))

    target = 34.0
    if high_prev >= 120:
        target = 42.0
    elif high_prev >= 95:
        target = 38.0
    if pressured:
        target += 10.0
    if endgame and hp <= 5:
        target += 8.0

    affordable_floor = 12.0
    if budget < target and budget > affordable_floor:
        target = max(affordable_floor, budget * 0.72)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for aid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((aid, o))

    if not alive:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for aid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Our target bid: aim to beat likely non-Cindy bids but avoid Cindy's extreme spending
    # Use supply as a rough proxy: when supply is high, we can bid less.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base aggressiveness from yesterday pressure
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Someone is willing to overpay; we only match partially
        base = max(DAILY_SALARY * 0.35, avg_prev_bid * 0.55)
    else:
        base = max(DAILY_SALARY * 0.5, avg_prev_bid * 0.6)

    # If we are in danger (low hp or many no-water days), bid more
    if my_hp <= 2 or my_no_water_days >= 2:
        base *= 1.35
    elif my_hp <= 4 or my_no_water_days >= 1:
        base *= 1.15

    # Adjust for supply: more supply -> bid less
    base *= (1.15 - 0.35 * supply_norm)

    # Cap to avoid bankrupting ourselves
    bid_cap = my_budget

    # Also avoid absurd bids beyond what would be needed for survival in typical ranges
    # (supply range 15-25, water requirement 9 => 1 unit usually; bid around salary fractions)
    hard_cap = DAILY_SALARY * 0.95
    target = min(bid_cap, min(hard_cap, base))

    # Ensure non-negative and at least small positive if budget allows
    if target < 0.0:
        target = 0.0
    if my_budget > 0.0 and target == 0.0:
        target = min(my_budget, DAILY_SALARY * 0.2)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, 20.0)

    avg_prev_bid = 0
    bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace:
            bids.append(trace['bid'])

    if bids:
        avg_prev_bid = sum(bids) / len(bids)

    # Aggressive bidding if HP is low
    if hp <= 3:
        return min(budget, max(avg_prev_bid * 1.1, DAILY_SALARY * 0.9))

    # Conservative bidding if supply is high
    if supply > 20:
        return min(budget, max(avg_prev_bid * 0.8, DAILY_SALARY * 0.4))

    # Balanced approach
    return min(budget, max(avg_prev_bid * 0.95, DAILY_SALARY * 0.6))
